const svg=body=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none">${body}</svg>`;
function channel(c){c/=255;return c<=0.03928?c/12.92:Math.pow((c+0.055)/1.055,2.4)}
function luminance(hex){const h=hex.replace('#','');const r=parseInt(h.substr(0,2),16),g=parseInt(h.substr(2,2),16),b=parseInt(h.substr(4,2),16);return 0.2126*channel(r)+0.7152*channel(g)+0.0722*channel(b)}
/** White ink when white/cover contrast reaches 4.5:1 (both contrasted against pure white/black, never grey). */
export function decideInk(hex){const L=luminance(hex);return (1.05/(L+0.05))>=4.5?'white':'black'}
/** Cover hex per Get Inspired theme, matching the library palette. */
export const THEME_HEX={'t-graphite':'#4a1c24','t-cognac':'#8b5a2b','t-black':'#1a1a1a','t-cream':'#1e2a3a','t-linen':'#a85b40','t-pink':'#dfd9ce','t-grey':'#c9a9b0','t-white':'#edeae2'};
export function notebookSymbol(index,coverHex){const p=pairs[index]||pairs[0];return svg(decideInk(coverHex||'#4a1c24')==='white'?p.white:p.black)}
